  async getAnalytics(months,user){if(!pool)return null;const [summary,monthly,types,statuses,engineers,customers]=await Promise.all([query(`select (select count(*)::int from jobs where company_id=$1 and status='Completed' and completed_at>=current_date-($2||' months')::interval) completed_jobs,(select count(*)::int from jobs where company_id=$1 and status not in ('Completed','Cancelled')) active_jobs,(select coalesce(sum(total-balance),0) from invoices where company_id=$1 and issued_at>=current_date-($2||' months')::interval) revenue,(select coalesce(sum(balance),0) from invoices where company_id=$1 and balance>0) outstanding,(select count(*)::int from customers where company_id=$1 and status='Active') active_customers,(select count(*)::int from service_requests where company_id=$1 and status in ('Submitted','Reviewing')) open_requests`,[user.companyId,months]),query(`with series as (select generate_series(date_trunc('month',current_date)-(($2-1)||' months')::interval,date_trunc('month',current_date),'1 month') as month_start) select to_char(s.month_start,'Mon YY') label,coalesce((select sum(i.total-i.balance) from invoices i where i.company_id=$1 and date_trunc('month',i.issued_at)=s.month_start),0) revenue,coalesce((select count(*) from jobs j where j.company_id=$1 and j.status='Completed' and date_trunc('month',j.completed_at)=s.month_start),0)::int completed from series s order by s.month_start`,[user.companyId,months]),query(`select job_type label,count(*)::int value from jobs where company_id=$1 and created_at>=current_date-($2||' months')::interval group by job_type order by value desc`,[user.companyId,months]),query(`select status label,count(*)::int value from jobs where company_id=$1 group by status order by value desc`,[user.companyId]),query(`select coalesce(e.full_name,j.engineer_name,'Unassigned') name,count(*)::int jobs,count(*) filter(where j.status='Completed')::int completed from jobs j left join engineer_profiles e on e.id=j.engineer_profile_id where j.company_id=$1 and j.created_at>=current_date-($2||' months')::interval group by coalesce(e.full_name,j.engineer_name,'Unassigned') order by completed desc,jobs desc limit 8`,[user.companyId,months]),query(`select c.company_name name,(select count(*)::int from jobs j where j.customer_id=c.id) jobs,(select coalesce(sum(i.total),0) from invoices i where i.customer_id=c.id) value from customers c where c.company_id=$1 order by value desc,jobs desc limit 8`,[user.companyId])]);const s=summary.rows[0];return{summary:{completedJobs:s.completed_jobs,activeJobs:s.active_jobs,revenue:Number(s.revenue),outstanding:Number(s.outstanding),activeCustomers:s.active_customers,openRequests:s.open_requests},monthly:monthly.rows.map(x=>({...x,revenue:Number(x.revenue)})),jobTypes:types.rows,jobStatuses:statuses.rows,engineers:engineers.rows,customers:customers.rows.map(x=>({...x,value:Number(x.value)}))};},
