  async listNotifications(user){
    if(!pool||!user.companyId)return[];
    const r=await query(`with events as (
      select 'request:'||r.id::text notification_key,'Service request' type,r.subject title,c.company_name||' submitted a '||lower(r.priority)||' priority request.' message,'/app/requests' link,r.created_at event_at
      from service_requests r join customers c on c.id=r.customer_id
      where r.company_id=$1 and r.status in ('Submitted','Reviewing')
      union all
      select 'quote:'||q.id::text||':'||q.status,'Quotation response',q.reference||' was '||lower(q.status),c.company_name||' responded to the quotation.','/app/quotes',coalesce(q.updated_at,q.created_at)
      from quotes q join customers c on c.id=q.customer_id
      where q.company_id=$1 and q.status in ('Accepted','Rejected')
      union all
      select 'job-complete:'||j.id::text,'Job completed',j.reference||' · '||j.title,c.company_name||' job has been completed and its service report is ready.','/app/jobs/'||j.id::text,coalesce(j.completed_at,j.updated_at)
      from jobs j join customers c on c.id=j.customer_id
      where j.company_id=$1 and j.status='Completed'
      union all
      select 'stock:'||i.id::text||':'||i.quantity::text,'Low stock',i.name||' · '||i.quantity::text||' remaining','Stock has reached or fallen below its reorder level of '||i.reorder_level::text||'.','/app/inventory',i.updated_at
      from inventory_items i where i.company_id=$1 and i.is_active=true and i.quantity<=i.reorder_level
    ) select e.notification_key "key",e.type,e.title,e.message,e.link,e.event_at "createdAt",(nr.notification_key is not null) "isRead"
      from events e left join notification_reads nr on nr.company_id=$1 and nr.user_uid=$2 and nr.notification_key=e.notification_key
      where e.event_at>=now()-interval '90 days' order by e.event_at desc limit 60`,[user.companyId,user.uid]);
    return r.rows;
  },
